	if (totalUsdcBorrowed() > ((totalAssets() - assets) * maxUtilizationBps) / MAX_BPS)
		revert MaxUtilizationBreached();

	// take out required assets from aave lending pool
	pool.withdraw(address(asset), assets, address(this));
}
